ch10_questions = []
for idx, q_tuple in enumerate(ch10_specs):
    num = q_tuple[0]
    q_text = q_tuple[1]
    opts = q_tuple[2]
    if len(q_tuple) == 5:
        topic = q_tuple[3]
        src = q_tuple[4]
    else:
        src = q_tuple[3]
        topic = get_ch10_topic(num)
    ans_idx = mapping[ch10_answers[idx]]
    ch10_questions.append({
        "id": f"ch10_{num}",
        "chapterId": 10,
        "number": num,
        "question": q_text,
        "options": opts,
        "correctAnswer": ans_idx,
        "topic": topic,
        "source": src
    })

with open('src/data/questions/ch10.ts', 'w', encoding='utf-8') as f:
    f.write(f"""import {{ Question }} from '../../types';\n\nexport const CHAPTER_10_QUESTIONS: Question[] = {json.dumps(ch10_questions, ensure_ascii=False, indent=2)};\n""")

print(f"Chapter 10 written with {len(ch10_questions)} questions.")
